definition.raw:
Let
\begin{align*}
  GL(\mathbb{R}^d) = \{ A \in \mathbb{R}^{d\times d} : \det( A ) \not= 0 \},
\end{align*}
be the general linear group of $\mathbb{R}^d$.

\label{def:invariant}
  For $w \in \mathbb{N}$,
  we call $\phi \in T(\R^\ds)$ an \textbf{GL invariant of weight $w$} if
  \begin{align*}
    \Big\langle S(A X)_{0,T}, \phi \Big\rangle = (\det A)^w \Big\langle S(X)_{0,T}, \phi \Big\rangle
  \end{align*}
  for all $A \in \operatorname{GL}(\mathbb{R}^d)$.

\label{def:action}
  Define a linear action of $GL(\mathbb{R}^d)$ on $T((\R^\ds))$ and $T(\R^\ds)$,
  by specifying on monomials
  \begin{align*}
    A x_{i_1} .. x_{i_n}
    &:=
    \sum_j (A e_{i_1})_{j_1} x_{j_1} .. (A e_{i_n})_{j_n} x_{j_n} \\
    &=
    \sum_j A_{j_1 i_1} .. A_{j_n i_n} x_{j_1} .. x_{j_n}.
  \end{align*}

Let $X: [0,T] \to \mathbb{R}^d$ be any curve.
	Define its \textbf{signed volume} to be the following limit, if it exists,
	\begin{align*}
	  \operatorname{Signed-Volume}(X)
	  :=
    \frac{1}{d!}
    \lim_{|\pi| \to 0}
    \sum_i
     \det\left[
       \begin{matrix}
         1 & 1 & .. & 1 \\

         X_{t^\pi_{i_0}} & X_{t^\pi_{i_1}} & .. & X_{t^\pi_{i_d}}
       \end{matrix}
     \right].
	\end{align*}
  Here $\pi = (0=t^\pi_0, .., t^\pi_{n^\pi}=T)$ is a partition of the interval $[0,T]$ and $|\pi|$ denotes its mesh size.
  The indices $i$ are chosen as in Lemma~\ref{lem:generalPiecewiseLinearCurve}.

Let
\begin{align*}
  SO(\mathbb{R}^d) = \{ A \in GL(\mathbb{R}^d) : A A^\top = \operatorname{id}, \det( A ) = 1 \},
\end{align*}
be the group of rotations of $\mathbb{R}^d$.

We call $\phi \in T(\mathbb{R}^d)$ an \textbf{SO invariant} if
  \begin{align*}
    \langle S(X)_{0,T}, \phi \rangle = \langle S(A X)_{0,T}, \phi \rangle
  \end{align*}
  for all $A \in SO(\mathbb{R}^d)$ and all curves $X$.

  Alternatively, as explained in Section~\ref{sec:gl},
  \begin{align*}
    A^\top \phi = \phi,
  \end{align*}
  for all $A \in SO(\mathbb{R}^d)$, where the action on $T(\R^\ds)$ was given in Definition~\ref{def:action}.

We call $\phi \in T(\mathbb{R}^d)$ a \textbf{permutation invariant} if
  \begin{align*}
    \Big\langle S( M(\sigma) X)_{0,T}, \phi \Big\rangle = \Big\langle S(X)_{0,T}, \phi \Big\rangle
  \end{align*}
  for all $\sigma \in S_d$ and all curves $X$.

  Alternatively, as explained in Section~\ref{sec:gl},
  \begin{align*}
    M(\sigma)^\top \phi = \phi,
  \end{align*}
  for all $\sigma \in S_d$.
  Equivalently,
  \begin{align*}
    M(\sigma) \phi = \phi,
  \end{align*}
  for all $\sigma \in S_d$,

Let
  \begin{align*}
    GL_0(\mathbb{R}^d) := \{ A \in GL(\mathbb{R}^{1+d}) : A e_0 = A^{-1} e_0 = e_0 \},

  \end{align*}
  the space of invertible maps of $\mathbb{R}^{1+d}$ leaving the first direction unchanged.

  We call $\phi \in T(\mathbb{R}^{1+d})$ a \textbf{$\widetilde{GL}$ invariant of weight $w$} if
  \begin{align*}
    A^\top \phi = (\det A)^w \phi,
  \end{align*}
  for all $A \in GL_0(\mathbb{R}^d)$.

Define the linear map of restriction to $U$
on polynomials of order $m$ by defining on monomials
\begin{align*}

  x_i|_U := x_{i|_U}
\end{align*}
so for example
\begin{align*}
  x_{i_1} x_{i_2} x_{i_3} |_{\{1,3\}} = x_{i_1} x_{i_3}.

theorem.raw:
\label{thm:linearBasis}

   The space of multilinear maps
   \begin{align*}
     \psi: \underbrace{\mathbb{R}^d \times \dots \times \mathbb{R}^d}_{n \text{ times}} \to \mathbb{R}
   \end{align*}
   that satisfy
   \begin{align*}
     \psi(A v_1, A v_2, \dots, A v_n) = (\det A)^w \psi(v_1, v_2, \dots, v_n)
   \end{align*}
   for all $A \in \operatorname{GL}(V)$ and $v_1, \dots, v_n \in V$
   is non-empty if and only if $n = w d$ for some integer $w \ge 1$.

  In that case, a linear basis is given by
  \begin{align*}
    \{ v \mapsto \det[ v_{C_1} ]  .. \det[ v_{C_w} ] \}
  \end{align*}
  where
  $C_i$ are the columns of $\Sigma$,
  and
  $\Sigma$ ranges over all standard Young tableaux corresponding to the partition $\lambda = \underbrace{(w, w, .., w)}_{d \text{ times}}$ of $n$.

  Here, for a sequence $C = (c_1,..,c_d)$, $v_C$ denotes the matrix
  of column vectors $v_{c_i}$, i.e.
  \begin{align*}
    v_C = (v_{c_1}, .., v_{c_d}).
  \end{align*}

Let $X: [0,T] \to \mathbb{R}^d$ a continuous curve of bounded variation.
	Then its signed volume exists and
	\begin{align*}
    \operatorname{Signed-Volume}(X)
    =
    \frac{1}{d !}
    \Big\langle S(X)_{0,T}, \firstInvariant{d} \Big\rangle
	\end{align*}

{bib:LK2007}}] 
  Let $V$ be a $d$-dimensional vector space with inner product $\langle \cdot, \cdot \rangle$.
  A basis for the space of multilinear maps
  \begin{align*}
    \psi: \underbrace{V \times \dots \times V}_{n \text{ times}} \to \mathbb{R}
  \end{align*}
  that satisfy
  \begin{align*}
    \psi(A v_1, A v_2, \dots, A v_n) = \psi(v_1, v_2, \dots, v_n)
  \end{align*}
  for all $A \in \operatorname{SO}(V)$ and $v_1, \dots, v_n \in V$ 
  is given by the maps
  \begin{align*}
    F = p\left(a^{(1)},b^{(1)}\right) \cdot .. \cdot p\left(a^{(r)},b^{(r)}\right) u\left(c^{(1)}\right) \cdot .. \cdot u\left(c^{(s)}\right),
  \end{align*}
  with $c^{(j)} \in I(d,n)$,
  $a^{(j)},b^{(j)} \in I(r,n), 1 \le r \le d-1$,
  \begin{align*}
    a^{(1)} \ge b^{(1)} \ge a^{(2)} \ge .. \ge b^{(r)} \ge c^{(1)} \ge .. \ge c^{(s)},
  \end{align*}
  and
  \begin{align*}
    \cup_j a^{(j)} \bigcup \cup_j b^{(j)} \bigcup \cup_j c^{(j)} = \{1, .., n\},
  \end{align*}
  is a \emph{disjoint} union (that is, every number $1,..,n$ appears in exactly one of the sequences $a^{(j)},b^{(j)},c^{(j)}$).
  In particular $n = C_1 \cdot 2 + C_2 \cdot d$ for some $C_1,C_2 \in \mathbb{N}$.

\label{thm:soInvariants}
  Define
  \begin{align*}
    z_1 &= x_1 + i x_2 \\
    z_2 &= x_1 - i x_2.
  \end{align*}
  The space of $SO$ invariants on level $n$ in $T(\mathbb{C}^2)$ is spanned freely by
  \begin{align*}
    z = z_{j_1} \cdot .. \cdot z_{j_n} \quad \text{ with } \quad \#\{ r : j_r = 1 \} = \#\{ r : j_r = 2 \}.
  \end{align*}


  The space of $SO$ invariants on level $n$ in $T(\mathbb{R}^2)$ is spanned freely by
  \begin{align*}
    \operatorname{Re}[ z ], \operatorname{Im}[ z ] \quad \text{ with } \quad \#\{ r : j_r = 1 \} = \#\{ r : j_r = 2 \} \text{ and } z_1 = 1.
  \end{align*}

lemma.raw:
\label{lem:shuffleIdentity}
  Let $X: [0,T] \to \mathbb{R}^d$ be a continuous curve of bounded variation, then for every $a,b \in T(\mathbb{R}^d)$
  \begin{align*}
    \Big\langle S(X)_{0,T}, a \Big\rangle
    \Big\langle S(X)_{0,T}, b \Big\rangle
    =
    \Big\langle S(X)_{0,T}, a \shuffle b \Big\rangle
  \end{align*}

\label{lem:chen}
  For curves $X: [0,T] \to \mathbb{R}^d, Y: [0,T] \to \mathbb{R}^d$ denote
  their concatenation
  \begin{align*}
    X \sqcup Y: [0,2T] \to \mathbb{R}^d,
  \end{align*}
  as $X_\cdot$ on $[0,T]$ and $Y_{\cdot-T} - Y_0 + X_T$ on $[T,2T]$.
  Then
  \begin{align*}
    S(X \sqcup Y)_{0,2T} = S(X)_{0,T} \cdot S(Y)_{0,T}.
  \end{align*}

\label{lem:oneToOne}
  The space of all multilinear maps on $\mathbb{R}^{d} \times \dots \times \mathbb{R}^{d}$ ($n$-times)
  is in a one-to-one correspondence with homogeneous polynomials of order $n$ in the non-commuting variables $x_1,\dots,x_d$
  by the following bijection
  \begin{align*}
    \psi \mapsto \mathsf{poly}(\psi) := \sum_{i_1, \dots, i_n \in \{1,\dots,d\}} \psi(e_{i_1}, e_{i_2}, \dots, e_{i_n}) x_{i_1} \cdot x_{i_2} \cdot .. \cdot x_{i_n},
  \end{align*}
  with $e_i$ being the $i$-th canonical basis vector of $\mathbb{R}^d$.

For all $A \in \mathbb{R}^{d \times d}$ and any curve $X$,
  \begin{align*}
    \Big\langle S(A X)_{0,T}, \phi \Big\rangle
    =
    \Big\langle S(X)_{0,T}, A^\top \phi \Big\rangle.
  \end{align*}

\label{lem:projectionIsInvariant}
  If $\phi \in T(\R^\ds)$ satisfies
  \begin{align*}
    B \phi = \phi,
  \end{align*}
  for some $B \in GL(\mathbb{R}^d)$ then
  \begin{align*}
    B \pi_n \phi = \pi_n \phi,
  \end{align*}
  for all $n \ge 1$.

\label{lem:multi}
  For $\psi: (\mathbb{R}^d)^{\times n} \to \mathbb{R}$ multilinear
  and
  $A \in GL(\mathbb{R}^d)$,
  \begin{align*}
    \mathsf{poly}[ \psi( A \cdot ) ] = A^\top \mathsf{poly}[ \psi ].
  \end{align*}

\label{lem:dxw1}

  In any dimension $d$
  and for any $r=0,1,..,d-1$
  \begin{align*}
    \firstInvariant{d}(x_1,..,x_d)
    =
    (-1)^{r}
    \sum_{j=1}^{d}
    (-1)^{j+1} \mathsf{InsertAfter}(x_j,r) \firstInvariant{d-1}( x_1, .., \widehat{x_j} .., x_d ),
  \end{align*}
  where $\widehat{x_j}$ denotes the omission of that argument.

  For $d$ odd,
  \begin{align*}
    \firstInvariant{d}(x_1,..,x_d)
    &=
    \sum_{j=1}^d
    (-1)^{j+1}
    x_j \shuffle \firstInvariant{d-1}( x_1, .., \widehat{x_j} .., x_d ).
  \end{align*}

\label{lem:closedCurveOddDimension}
  If the ambient dimension $d$ is odd and the curve $X$ is closed (i.e. $X_T = X_0$) then
  \begin{align*}
    \Big\langle S(X)_{0,T}, \firstInvariantd \Big\rangle = 0.
  \end{align*}

\label{lem:lastPoint}
  If the ambient dimension $d$ is even, then for any curve $X$
  \begin{align*}
    \Big\langle S(X)_{0,T}, \firstInvariantd \Big\rangle
    =
    \Big\langle S(\bar X)_{0,T}, \firstInvariantd \Big\rangle,
  \end{align*}
  where $\bar X$ is $X$ concatenated with the straight line connecting $X_T$ to $X_0$.

\label{lem:invariantVolume}
  Let $X$ be the piecewise linear curve
  through $p_0,..,p_{d} \in \mathbb{R}^d$.
  Then
  \begin{align*}
    \Big\langle S(X)_{0,T}, \firstInvariantd \Big\rangle
    =
   \det\left[
     \begin{matrix}
       1 & 1 & .. & 1 \\
       p_0 & p_1 & .. & p_{d}
     \end{matrix}
   \right]
  \end{align*}

\label{lem:generalPiecewiseLinearCurve}
  Let $X$ be the piecewise linear curve through,
  $p_0,..,p_n \in \mathbb{R}^d$, with $n \ge d$.

  Then,
  \begin{align}
    \label{eq:invDet}
    \Big\langle S(X)_{0,T}, \firstInvariantd \Big\rangle
    =
    \sum_i
     \det\left[
       \begin{matrix}
         1 & 1 & .. & 1 \\
         p_{i_0} & p_{i_1} & .. & p_{i_{d}}
       \end{matrix}
     \right].
  \end{align}
  Here, for $d$ even, the subsequences $i$ are chosen as follows:
  \begin{align*}
    i_0 = 0
  \end{align*}
  and $i_1,..,i_{d}$ ranges over all possible increasing
  subsequences of $1,2,..,n$ such that
  for $\ell$ odd: $i_\ell + 1 = i_{\ell+1}$

  For $d$ odd, they are chosen as follows:
  \begin{align*}
    i_0 &= 0 \\
    i_{d} &= n,
  \end{align*}
  and $i_1,..,i_{d-1}$ ranges over all possible increasing
  subsequences of $1,2,..,n-1$ such that
  for $\ell$ odd: $i_\ell + 1 = i_{\ell+1}$

\label{lem:momentCurve}
  Let $X$ be the moment curve
  \begin{align*}
    X_t = (t,t^2,...,t^d) \in \mathbb{R}^d.
  \end{align*}
  Then for any $T > 0$
  \begin{align*}
    \frac{1}{d !} \Big\langle S(X)_{0,T}, \firstInvariant{d} \Big\rangle
    =
    |\operatorname{Convex-Hull}( X_{[0,T]} )|
  \end{align*}

For $\sigma \in S_d$,
  define $M(\sigma) \in GL(\mathbb{R}^d)$ as
  \begin{align*}
    M(\sigma)_{ij} = 1 \qquad \text{ if } i = \sigma(j).
  \end{align*}

  Then $M: S_d \to GL(\mathbb{R}^d)$ is a group homomorphism
  and
  moreover $M(\sigma^{-1}) = M(\sigma)^\top$.
  \footnote{$M$ is sometimes called the \emph{defining representation} of $S_d$.}

Consider the two closed curves $X^+$ and $X^-$ in $\mathbb{R}^2$, given for $t$ in $[0,2\pi]$ as



  \begin{align*}
    X^{\pm,1}_t &=\pm\cos t\\
    X^{\pm,2}_t &=\sin 2t.
  \end{align*}

  Then all the expressions \eqref{eq:expression} coincide on $X^+$ and $X^-$.

proposition.raw:
\label{prop:glInvariants}
  A linear basis for the space of $GL$ invariants of order $n = w d$ is given by
  \begin{align*}
    \sum_{i_1,\dots,i_n \in \{1,\dots,d\}} g_\Sigma(i_1,i_2,\dots,i_n) x_{i_1} x_{i_2} \dots x_{i_n},
  \end{align*}
  where
  \begin{align*}
    g_\Sigma(v) = \det[ v_{C_1} ]  .. \det[ v_{C_w} ],
  \end{align*}
  where
  $C_i$ are the columns of $\Sigma$,
  and
  $\Sigma$ ranges over all standard Young tableaux corresponding to the partition $\lambda = \underbrace{(w, w, .., w)}_{d \text{ times}}$ of $n$.

\label{prop:soInvariants}
  The $SO$ invariants of homogeneity $n$ are spanned by
  \begin{align*}
    \mathsf{poly}( \Psi ),
  \end{align*}
  where $\Psi$ ranges over the invariants of the previous theorem
  and $\mathsf{poly}$ is given in Lemma~\ref{lem:oneToOne}.

