\begin{proof}
  \textbf{The case $d=2$}\\


  Let $X$ be the curve through the points $p_0,p_1,..,p_n$,
  we can write it as concatenation
  of the curves $X^{(i)}$ where $X^{(i)}$ is the curve through
  the points $p_0 p_i, p_{i+1}, p_0$.
  The interval of definition for these curves (and all curves
  in this proof) do not matter, so we omit the subscript of $S(.)$.

  Then, by Chen's lemma (Lemma \ref{lem:chen})
  \begin{align*}
    \Big\langle S(X), \word{12} - \word{21} \Big\rangle
    &=
    \Big\langle S(X^{(n-1)}) \cdot .. \cdot S(X^{(1)}), \word{12} - \word{21} \Big\rangle \\
    &=
    \sum_{i=1}^{n-1} \Big\langle S(X^{(i)}), \word{12} - \word{21} \Big\rangle.
  \end{align*}
  For the last equality we used that
  \begin{align*}
    \Big\langle g h, \word{12} - \word{21}\Big\rangle
    =
    \Big\langle g, \word{12} - \word{21}\Big\rangle
    +
    \Big\langle h, \word{12} - \word{21}\Big\rangle
    +
    \Big\langle g, \word{1} \Big\rangle \Big\langle h, \word{2} \Big\rangle
    -
    \Big\langle g, \word{2} \Big\rangle \Big\langle h, \word{1} \Big\rangle,
  \end{align*}
  and that the increments of all curves $X^{(i)}$ are zero.
  Now by Lemma~\ref{lem:lastPoint}
  we can omit the last straight line in every $X^{(i)}$ and hence
  by Lemma~\ref{lem:invariantVolume}
  \begin{align*}
    \langle S(X^{(i)}), \word{12} - \word{21} \rangle
    =
     \det\left[
       \begin{matrix}
         1       & 1   & 1 \\
         p_{0} & p_{i} & p_{i+1}
       \end{matrix}
     \right],
  \end{align*}
  which finishes the proof for $d=2$.


  ~\\

  Now assume the statement is true for all dimensions strictly smaller than some $d$. We show it is true for $d$.

  \textbf{$d$ is odd }\\
  As before we can assume $p_0 = 0$ and that $p_n$ lies on the $x_1$ axis.
  Every sequence summed over on the right-hand side of \eqref{eq:invDet}
  is of the form $i = (0,...,n)$.
  For each of those, we calculate
  \begin{align*}
     \det\left[
       \begin{matrix}
         1       & 1       & .. & 1             & 1 \\
         p_{i_0} & p_{i_1} & .. & p_{i_{d-1}} & p_{i_d}
       \end{matrix}
     \right]
     =
     \det\left[
       \begin{matrix}
         1 & 1       & .. & 1             & 1 \\
         0 & p_{i_1} & .. & p_{i_{d-1}} & \Delta \cdot e_1
       \end{matrix}
     \right]
     =
     \Delta \cdot
     \det\left[
       \begin{matrix}
         1 & 1            & .. & 1 \\
         0 & \bar p_{i_1} & .. & \bar p_{i_{d-1}}
       \end{matrix}
     \right].
  \end{align*}
  Here $\bar p_j \in \mathbb{R}^{d-1}$ is obtained by deleting the first coordinate of $p_j$,
  $e_1$ is the first canonical coordinate vector in $\mathbb{R}^d$
  and $\Delta := (p_0 - p_n)_1 = \langle S(X), x_1 \rangle$ is the total increment of $X$ in the $x_1$ direction.
  Here we used that $d$ is odd (otherwise we would get a prefactor $-1$).

  This is the expression for the summands of the right-hand side of \eqref{eq:invDet},
  with dimension $d -1$ and points $0 = \bar p_0, \bar p_1, .., \bar p_{n-1}$.




  By assumption, summing up all these determinants gives
  \begin{align*}
    \Delta \cdot \Big\langle S(\bar X), \firstInvariant{d-1} \Big\rangle
    =
    \Big\langle S(X), x_1 \Big\rangle \Big\langle S(\bar X), \firstInvariant{d-1} \Big\rangle,
  \end{align*}
  where $\bar X$ is the curve in $\mathbb{R}^{d-1}$ through the points $\bar p_0, .. \bar p_{n-1}$.

  Since $\bar p_n = \bar p_0 = 0$,
  we can attach the additional point $\bar p_n$ to $\bar X$ without changing the value here (Lemma~\ref{lem:lastPoint}).
  Hence the sum of determinants is equal to
  \begin{align*}
    \Big\langle S(X), x_1 \Big\rangle \Big\langle S(X), \firstInvariant{d-1}(x_2,..,x_d) \Big\rangle,
  \end{align*}

  By Lemma~\ref{lem:dxw1} this is equal to $\langle S(X), \firstInvariant{d} \rangle$, which finishes the proof for odd $d$.

  ~\\

  \textbf{$d$ is even }


  We proceed by induction on $n$.
  For $n=d$ the statement follows from Lemma~\ref{lem:invariantVolume}.

  Let it be true for some $n$.
  Write $X = X'' \sqcup X'$ where $X'$ is the linear interpolation
  of $p_0, .., p_n$, $X''$ is the linear path from $p_n$ to $p_{n+1}$
  and we recall concatenation $\sqcup$ of paths from Lemma \ref{lem:chen}.

  Adding an additional point $p_{n+1}$,
  the sum on the right hand side of \eqref{eq:invDet}
  gets additional indices of the form
  \begin{align*}
    (p_{j_0}, .., p_{j_{d-1}}, p_{n+1}),
  \end{align*}
  where
  \begin{align*}
    j_0 &= 0 \\
    j_{d-1} &= n,
  \end{align*}
  and $j_1,..,j_{d-2}$ ranges over all possible increasing
  subsequences of $1,2,..,n-1$ such that
  for $\ell$ odd $j_\ell + 1 = j_{\ell+1}$.



  Assume $p_{n+1} - p_n = \Delta \cdot e_1$ lies on the $x_1$-axis.
  Then, summing over those $j$,
  \begin{align*}
    \sum_j
     \det\left[
       \begin{matrix}
         1 & 1 & .. & 1 & 1 & 1 \\
         0 & p_{j_1} & .. & p_{j_{d-2}} & p_{n} & p_{n+1}
       \end{matrix}
     \right]


















    &=
    \sum_j
     \det\left[
       \begin{matrix}
         1             & 1             & .. & 1 & 1 & 1 \\
         - p_n & p_{j_1} - p_n & .. & p_{j_{d-2}} - p_n & 0 & p_{n+1} - p_n
       \end{matrix}
     \right] \\
    &=
    \sum_j
     \det\left[
       \begin{matrix}
         1             & 1             & .. & 1 & 1 & 1 \\
         - p_n & p_{j_1} - p_n & .. & p_{j_{d-2}} - p_n & 0 & \Delta \cdot e_1
       \end{matrix}
     \right] \\
    &=
    \Delta \cdot
    \sum_j
     \det\left[
       \begin{matrix}
         1             & 1             & .. & 1 & 1 \\
         - \bar p_n & \bar p_{j_1} - \bar p_n & .. & \bar p_{j_{d-2}} - \bar p_n & 0
       \end{matrix}
     \right] \\
    &=
    \Delta \cdot
    \sum_j
     \det\left[
       \begin{matrix}
         1             & 1             & .. & 1 & 1 \\
         0 & \bar p_{j_1} & .. & \bar p_{j_{d-2}} & \bar p_n
       \end{matrix}
     \right] \\
     &=
    \Delta
    \cdot
    \Big\langle S(X'), \firstInvariant{d-1}(x_2, .., x_d) \Big\rangle
  \end{align*}
  Here we used that the indices $j$ range over the ones used in dimension $d-1$
  on the points $\bar p_0, .., \bar p_n$.

  On the other hand,
  \begin{align*}
    \Big\langle S(X), \firstInvariant{d} \Big\rangle 
    &=
    \Big\langle S(X'') S(X'), \firstInvariant{d} \Big\rangle \\
    &=
    \Big\langle S(X'), \firstInvariant{d} \Big\rangle
    +
    \Big\langle S(X''), x_1 \Big\rangle
    \Big\langle S(X'), \firstInvariant{d-1}(x_2, .., x_d) \Big\rangle.
  \end{align*}
  Here we used that $S(X'') = \exp( \Delta \cdot x_1 ) = 1 + \Delta \cdot x_1 + O(x_1^2)$
  and that each monomial in $\firstInvariant{d}$ has exactly one occurrence of $x_1$.

  This finishes the proof.
\end{proof}






\begin{definition}	
	Let $X: [0,T] \to \mathbb{R}^d$ be any curve.
	Define its \textbf{signed volume} to be the following limit, if it exists,
	\begin{align*}
	  \operatorname{Signed-Volume}(X)
	  :=
    \frac{1}{d!}
    \lim_{|\pi| \to 0}
    \sum_i
     \det\left[
       \begin{matrix}
         1 & 1 & .. & 1 \\

         X_{t^\pi_{i_0}} & X_{t^\pi_{i_1}} & .. & X_{t^\pi_{i_d}}
       \end{matrix}
     \right].
	\end{align*}
  Here $\pi = (0=t^\pi_0, .., t^\pi_{n^\pi}=T)$ is a partition of the interval $[0,T]$ and $|\pi|$ denotes its mesh size.
  The indices $i$ are chosen as in Lemma~\ref{lem:generalPiecewiseLinearCurve}.
\end{definition}

\begin{proof}
	Fix some sequence $\{\pi^n\}_{n\in\mathbb{N}}$,
  of partitions of $[0,T]$ with $|\pi^n| \to 0$ and interpolate 	$X$ linearly along each $\pi^n$ to obtain a sequence of linearly interpolated curves $X^n$.
	Then by Lemma~\ref{lem:generalPiecewiseLinearCurve}
	\begin{align*}
    \operatorname{Signed-Volume}(X^n)
    =
    \frac{1}{d!}
    \Big\langle S(X^n)_{0,T}, \firstInvariant{d} \Big\rangle
	\end{align*}
	By stability of the signature in the class of continuous curves of bounded variation (\cite[Proposition 1.28, Proposition 2.7]{bib:FV2010}),
  we get convergence
	\begin{align*}
    \Big\langle S(X^n)_{0,T}, \firstInvariant{d} \Big\rangle
    \to
    \Big\langle S(X)_{0,T}, \firstInvariant{d} \Big\rangle
	\end{align*}
	and this is independent of the particular sequence $\pi^n$ chosen.
\end{proof}

The previous theorem is almost a tautology, but there are relations to classical objects in geometry.
For $d=2$, as we have seen in Section~\ref{sec:d2w1},
\begin{align*}
  \frac{1}{2} \Big\langle S(X)_{0,T}, \firstInvariant{2} \Big\rangle,
\end{align*}
is equal to the signed area of the curve $X$.
In general dimension, the value of the invariant is related
to some kind of classical ``volume'' if the curve satisfies
some kind of monotonicity.
This is in particular satisfied for the ``moment curve''.

\begin{remark}
  It is easily verified that for integers $n_1 .. n_d$ one has
  \begin{align*}
    \frac{1}{n_1 \cdot .. \cdot n_d}
    \int_0^T dt_1^{n_1} .. dt_d^{n_d}
    =
    \frac{1}{n_1}
    \frac{1}{n_1+n_2}
    ..
    \frac{1}{n_1+..+n_d}
    T^{n_1+..+n_d}.
  \end{align*}
  We deduce that
  \begin{align*}
    |\operatorname{Convex-Hull}( X_{[0,T]} )|
    =
    T^{1+2+..+d}
    \sum_{\sigma\in S_d} \operatorname{sign} \sigma
    \frac{1}{\sigma(1)}
    \frac{1}{\sigma(1)+\sigma(2)}
    ..
    \frac{1}{\sigma(1)+..+\sigma(d)}.
  \end{align*}

  In \cite[Section 15]{bib:KS1953}, 
  the value of this volume is determined,
  for $T=1$, as
  \begin{align*}
    \prod_{\ell=1}^d \frac{(\ell-1)! (\ell-1)!}{((2\ell-1)!}.
  \end{align*}

  We hence get the combinatorial identity
  \begin{align*}
    \prod_{\ell=1}^d \frac{(\ell-1)! (\ell-1)!}{(2\ell-1)!}
    =
    \sum_{\sigma\in S_d}
    \operatorname{sign} \sigma
    \frac{1}{\sigma(1)}
    \frac{1}{\sigma(1)+\sigma(2)}
    ..
    \frac{1}{\sigma(1)+..+\sigma(d)}.
  \end{align*}
\end{remark}
\begin{proof}
  For $n\ge d$ let $0 = t_0 <  .. < t_n \le T$ be time-points, let $p_i := X_{t_i}$ be
  the corresponding points on the moment curve
  and denote by $X^n$ the piecewise linear curve through those points.

  We will show
  \begin{align*}
    \frac{1}{d !} \Big\langle S(X^n)_{0,T}, \firstInvariant{d} \Big\rangle
    =
    |\operatorname{Convex-Hull}( X^n_{[0,T]} )|.
  \end{align*}

  The convex hull of the point $\{p_i\}$ (equivalently: the convex hull of $X^n$)
  is known as the \emph{cyclic polytope} $C_d(n)$ \cite[Section 15.5.1.4]{bib:TOG2004}.

  A \emph{triangulation of a polytope} in dimension $d$ concerns its 
  (disjoint, up to to measure zero) decomposition
  into simplices of dimension $d$ (\cite[Chapter 16]{bib:TOG2004}).
  In particular $\{p_0, .., p_n \} = \cup_\ell S_\ell$ with $|S_\ell| = d+1$
  and
  \begin{align*}
    |\operatorname{Convex-Hull}( p_0,..,p_n )|
    =
    \sum_\ell |\operatorname{Convex-Hull}( S_\ell )|.
  \end{align*}

  We will show that the index sets summed over in 
  Lemma~\ref{lem:generalPiecewiseLinearCurve} form
  a certain kind of triangulation for $p_0,..,p_n$.

  The \emph{pulling triangulation} of $p_0,..,p_n$ with respect to $p_0$ is formed as follows:
  form all subset $p_0 \cup I$ where
  $I$ ranges over all $d$ points in $p_1,..,p_n$ such that they form
  a $d-1$-dimensional face (a facet) of the cyclic polytope.
  For any polytope, successively pulling each vertex results
  in a triangulation, see \cite[Chapter 16]{bib:TOG2004}. 
  For the polytope under consideration it is sufficient to pull one vertex, since
  all vertices lie on the boundary of the convex hull.

  By Gale's evenness criterion (\cite[Theorem 3]{bib:Gal1963})
  the points $p_{i_1}, .., p_{i_d}$,
  with distinct $i_j \in \{0,..,n\}$ form a facet if and only if 
  any two elements of $\{0,..,n\} \setminus \{i_1, .., i_d\}$
  are separated by an even number of elements in $\{i_1, .., i_d\}$.
  \footnote{

    For example,
    with $n=4$ and dimension $d=2$,
    the indices $\{0,1,2\}$,$\{0,2,3\}$,$\{0,3,4\}$,$\{0,1,4\}$,$\{1,2,4\}$,$\{2,3,4\}$
    lead to facets.
  }

  \textbf{$d$ odd}\\
  For the pulling triangulation, we are looking for such $\{i_j\}$ such that $i_1 \ge 1$.
  Those are exactly the indices with
  \begin{itemize}
    \item $i_{\ell+1} = i_\ell + 1$ for $\ell$ odd
    \item $i_d = n$.
  \end{itemize}
  Together with $i_0 := 0$ these form the indices of Lemma~\ref{lem:generalPiecewiseLinearCurve}.


  \textbf{$d$ even}\\
  We are looking for such $\{i_j\}$ such that $i_1 \ge 1$.
  Those are exactly the indices with
  \begin{itemize}
    \item $i_{\ell+1} = i_\ell + 1$ for $\ell$ odd.
  \end{itemize}
  Together with $i_0 := 0$ these form the indices of Lemma~\ref{lem:generalPiecewiseLinearCurve}.

  Hence
  \begin{align*}
    |\operatorname{Convex-Hull}( X^n_{[0,T]} )|
    =
    \sum_i |\operatorname{Convex-Hull}( p_{i_0}, .., p_{i_d} )|.
  \end{align*}
  Now by Lemma~\ref{lem:relationToClassicalVolume}
  \begin{align*}
    |\operatorname{Convex-Hull}( p_{i_0}, .., p_{i_d} )|
    =
    \frac{1}{d!}
    \left|
    \det\left[
      \begin{matrix}
        1 & 1 & .. & 1 \\
        p_{i_0} & p_{i_1} & .. & p_{i_d}
      \end{matrix}
    \right]
    \right|.
  \end{align*}
  The determinant is in fact positive here, since
  it is a Vandermonde determinant and can be written as
  \begin{align*}
    \prod_{0\le \ell < k \le n} ( t_{i_k} - t_{i_\ell} ) > 0.
  \end{align*}
  We can hence omit the modulus and get
  \begin{align*}
    |\operatorname{Convex-Hull}( p_{i_0}, .., p_{i_d} )|
    &=
    \frac{1}{d!}
    \det\left[
      \begin{matrix}
        1 & 1 & .. & 1 \\
        p_{i_0} & p_{i_1} & .. & p_{i_d}
      \end{matrix}
    \right] \\
    &=
    \Big\langle S(X^n)_{0,T}, \firstInvariantd \Big\rangle,
  \end{align*}
  by Lemma~\ref{lem:generalPiecewiseLinearCurve}.

  The statement of the lemma now follows by piecewise linear approximation of $X$
  using continuity of the convex hull, which follows from \cite[Lemma 3.2]{bib:EN2010},
  and of iterated integrals \cite[Proposition 1.28, Proposition 2.7]{bib:FV2010}.




\end{proof}

\begin{remark}
  In particular for $d=2$ and $n$ even, the dimension of rotation invariants on level $n$ in $T(\mathbb{R}^2)$
  is equal to

  $\binom{n}{n/2}$.
\end{remark}
\begin{proof}
  1. \textbf{$z$ is invariant}\\
  Let
  \begin{align*}
    A_\theta :=
    \begin{pmatrix}
      \cos(\theta) & \sin(\theta) \\
      -\sin(\theta) & \cos(\theta)
    \end{pmatrix}
  \end{align*}

  Then (recall Definition~\ref{def:action})
  \begin{align*}
    A_\theta^\top z_1
    &=
    A_\theta^\top (x_1 + i x_2) \\
    &=
    \cos(\theta) x_1 + \sin(\theta) x_2
    +
    i \left( -\sin(\theta) x_1 + \cos(\theta) x_2 \right) \\
    &=
    e^{-i\theta} z_1 \\
    A_\theta^\top z_2 &= e^{i\theta} z_2.
  \end{align*}
  Hence
  \begin{align*}
    A_\theta^\top z_{j_1} \cdot .. \cdot z_{j_n} = z_{j_1} \cdot .. \cdot z_{j_n} \forall \theta
    \quad
    \text{ if and only }
    \quad
    \#\{ r : j_r = 1 \} = \#\{ r : j_r = 2 \}.
  \end{align*}

  2. \textbf{They form a basis}\\
  Now $x_{j_1} .. x_{j_n}: j_\ell \in \{1,2\}$ is a basis of $\pi_n T(\mathbb{C}^2)$ with respect to $\mathbb{C}$.
  Hence $z_{j_1} .. z_{j_n}$ is (the map $(x_1,x_2) \mapsto (z_1,z_2)$ is invertible).
  By Step 1 we have hence exhibited a basis (with respect to $\mathbb{C}$) for all invariants in $\pi_n T(\mathbb{C}^2)$.

  3. \textbf{Real invariants}\\
	The space of $SO$ invariants on level $n$ in $T(\mathbb{C}^2)$ is spanned freely by the set of
	\begin{align*}
	z_{j_1} \cdot .. \cdot z_{j_n} \quad \text{ with } \quad \#\{ r : j_r = 1 \} = \#\{ r : j_r = 2 \}.
	\end{align*}
	Adding and subtracting the elements with $j_1=2$ from the elements with $j_1=1$, we get that the space of $SO$ invariants on level $n$ in $T(\mathbb{C}^2)$ is spanned freely by the set of
	\begin{align*}
	 & (z_{j_1} \cdot .. \cdot z_{j_n} + z_{3-j_1} \cdot .. \cdot z_{3-j_n}) \quad\text{and}\quad (z_{j_1} \cdot .. \cdot z_{j_n} - z_{3-j_1} \cdot .. \cdot z_{3-j_n}) 
	 \\&\quad \text{ with } \quad \#\{ r : j_r = 1 \} = \#\{ r : j_r = 2 \}\text{ and $j_1=1$}.
	\end{align*}
	Because $z_{3-j_1} \cdot .. \cdot z_{3-j_n}$ is the complex conjugate of $z_{j_1} \cdot .. \cdot z_{j_n}$, this means that the space of $SO$ invariants on level $n$ in $T(\mathbb{C}^2)$ is spanned freely by the set of
		\begin{align*}
	& \operatorname{Re}(z_{j_1} \cdot .. \cdot z_{j_n}) \quad\text{and}\quad \operatorname{Im}(z_{j_1} \cdot .. \cdot z_{j_n}) 
	\\&\quad \text{ with } \quad \#\{ r : j_r = 1 \} = \#\{ r : j_r = 2 \}\text{ and $j_1=1$}.
	\end{align*}
	This is an expression for a basis of the SO invariants in terms of real combinations of basis elements of the tensor space. They thus form a basis for the SO invariants for the free \emph{real} vector space on the same set, namely $\pi_n T(\mathbb{R}^2)$.
\end{proof}



