\begin{definition}
  We call $\phi \in T(\mathbb{R}^d)$ a \textbf{permutation invariant} if
  \begin{align*}
    \Big\langle S( M(\sigma) X)_{0,T}, \phi \Big\rangle = \Big\langle S(X)_{0,T}, \phi \Big\rangle
  \end{align*}
  for all $\sigma \in S_d$ and all curves $X$.

  Alternatively, as explained in Section~\ref{sec:gl},
  \begin{align*}
    M(\sigma)^\top \phi = \phi,
  \end{align*}
  for all $\sigma \in S_d$.
  Equivalently,
  \begin{align*}
    M(\sigma) \phi = \phi,
  \end{align*}
  for all $\sigma \in S_d$,
\end{definition}





We follow \cite[Section 3]{bib:BRRZ2005}.

To a monomial
\begin{align*}
  x_{i_1}\cdot .. \cdot x_{i_n},
\end{align*}
we associate the following set partition  of $[n] := \{1, .., n \}$
\begin{align*}
  \nabla(  x_{i_1} \cdot .. \cdot x_{i_n} )
  :=
  \{ \{ \ell : i_\ell = p \} : p \in [d] \} \setminus \{ \{ \} \}.
\end{align*}

\begin{example}
  Let $d=3$, then
  \begin{align*}
    \nabla(  x_2 x_3 x_2 x_2 x_1 )
    =
    \{ \{1, 3, 4\}, \{2\}, \{5\} \}.
  \end{align*}
\end{example}

Note that for every permutation $\sigma \in S_d$,
\begin{align}
  \label{eq:permuation}
  \nabla( x_{i_1}\cdot .. \cdot x_{i_n} ) = \nabla( x_{\sigma(i_1)} \cdot .. \cdot x_{\sigma(i_n)} ).
\end{align}

\begin{proof}
  By \eqref{eq:permuation}, each $M_A$ is permutation invariant.
  Moreover, since $|A| \le d$, $M_A$ is nonzero.

  For $A, A'$ distinct set partitions of $[n]$
  the monomials in $M_A$ and the monomials in $M_{A'}$ do not overlap.
  Hence the proposed basis is linearly independent.

  Now, if $\phi$ is permutation invariant
  and if for some $i, i'$,
  $\nabla( x_{i_1} .. x_{i_n} ) = \nabla( x_{i'_1} .. x_{i'_n} )$ then
  the coefficient of $x_i$ and $x_{i'}$ must coincide.

  Hence the proposed basis spans invariants of homogeneity $n$.
\end{proof}

