\label{rem:interpretation}

  Let us make clear that from the perspective of data analysis,
  the ``invariant'' of interest is really the action of this element in $T(\R^\ds)$
  on the signature of a curve.

  In this example, the real number
  \begin{align*}
    \Big\langle S(X)_{0,T}, \word{12} - \word{21} \Big\rangle
    =  
    \int_0^T \int^{r_2} dX^1_{r_1} dX^2_{r_2}
    -
    \int_0^T \int^{r_2} dX^1_{r_1} dX^2_{r_2},

  \end{align*}
  changes only by the determinant of $A \in GL(\mathbb{R}^2)$ when
  calculating it for the transformed curve $A X$:
  \begin{align*}
    \Big\langle S(A X)_{0,T}, \word{12} - \word{21} \Big\rangle = \det(A)\ \Big\langle S(X)_{0,T}, \word{12} - \word{21} \Big\rangle.
  \end{align*}

For completeness, we also note the related \emph{de Bruijn's formula}.
  For $d$ even,
  \begin{align*}
    \firstInvariant{d}(x_1,..,x_d)
    =
    \operatorname{Pf}_\shuffle[ A ],
  \end{align*}
  where
  \begin{align*}
    A_{ij}
    = 
    \firstInvariant{2}(x_i,x_j),
  \end{align*}
  and the Pfaffian (with respect to the shuffle product), is
  \begin{align*}
    \operatorname{Pf}_\shuffle[ A ]
    =
    \frac{1}{2^{d/2} (d/2)!}
    \sum_{\sigma \in S_{d}} \operatorname{sign}(\sigma)

    A_{\sigma(1),\sigma(2)}
    \shuffle
    A_{\sigma(3),\sigma(4)}
    \shuffle
    ..
    \shuffle
    A_{\sigma(d-1),\sigma(d)}.
  \end{align*}

  For a proof see \cite{bib:DB1955}
  and \cite{bib:LT2002}.

In both the odd and the even case,
  there are
  \begin{align*}
    \binom{\lfloor d/2 \rfloor + n - d - 1 }{ n - d -1 }
  \end{align*}
  indices summed over.

It is easily verified that for integers $n_1 .. n_d$ one has
  \begin{align*}
    \frac{1}{n_1 \cdot .. \cdot n_d}
    \int_0^T dt_1^{n_1} .. dt_d^{n_d}
    =
    \frac{1}{n_1}
    \frac{1}{n_1+n_2}
    ..
    \frac{1}{n_1+..+n_d}
    T^{n_1+..+n_d}.
  \end{align*}
  We deduce that
  \begin{align*}
    |\operatorname{Convex-Hull}( X_{[0,T]} )|
    =
    T^{1+2+..+d}
    \sum_{\sigma\in S_d} \operatorname{sign} \sigma
    \frac{1}{\sigma(1)}
    \frac{1}{\sigma(1)+\sigma(2)}
    ..
    \frac{1}{\sigma(1)+..+\sigma(d)}.
  \end{align*}

  In \cite[Section 15]{bib:KS1953}, 
  the value of this volume is determined,
  for $T=1$, as
  \begin{align*}
    \prod_{\ell=1}^d \frac{(\ell-1)! (\ell-1)!}{((2\ell-1)!}.
  \end{align*}

  We hence get the combinatorial identity
  \begin{align*}
    \prod_{\ell=1}^d \frac{(\ell-1)! (\ell-1)!}{(2\ell-1)!}
    =
    \sum_{\sigma\in S_d}
    \operatorname{sign} \sigma
    \frac{1}{\sigma(1)}
    \frac{1}{\sigma(1)+\sigma(2)}
    ..
    \frac{1}{\sigma(1)+..+\sigma(d)}.
  \end{align*}

Let $d=3$, then
  \begin{align*}
    \nabla(  x_2 x_3 x_2 x_2 x_1 )
    =
    \{ \{1, 3, 4\}, \{2\}, \{5\} \}.
  \end{align*}

\label{ex:permInvariants}
  Consider $d=3$

  Order $n=1$
  \begin{align*}
    \word{1} + \word{2} + \word{3}
  \end{align*}

  Order $n=2$
  \begin{align*}
    &\word{33} + \word{22} + \word{11}  \\
    &\word{32} + \word{31} + \word{23} + \word{21} + \word{13} + \word{12}
  \end{align*}

  Order $n=3$
  \begin{align*}
    &\word{333} + \word{222} + \word{111} \\
    &\word{332} + \word{331} + \word{223} + \word{221} + \word{113} + \word{112} \\
    &\word{323} + \word{313} + \word{232} + \word{212} + \word{131} + \word{121} \\
    &\word{322} + \word{311} + \word{233} + \word{211} + \word{133} + \word{122} \\
    &\word{321} + \word{312} + \word{231} + \word{213} + \word{132} + \word{123}
  \end{align*}

Here the sum is over all permutations $\pi$ that leave the elements of each \emph{row} of $t$ unchanged.
